1	'use strict';
2	// Collaboration message service — WebSocket relay.
3	//
4	// Chat clients from other hosts open a WebSocket to this service and it relays their
5	// frames. The service listens for external handshakes on all interfaces; each connected
6	// client's messages are echoed back to it (the room-relay hook is wired on top of this
7	// in the platform, omitted here). This is the process whose `ws` build the platform
8	// attests on each round-trip.
9	const WebSocket = require('ws');
10	
11	const HOST = process.env.COLLAB_HOST || '0.0.0.0';
12	const PORT = process.env.COLLAB_PORT ? Number(process.env.COLLAB_PORT) : 8081;
13	
14	// Accept external WebSocket handshakes with the server's default options.
15	const wss = new WebSocket.Server({ host: HOST, port: PORT });
16	
17	wss.on('connection', (socket) => {
18	  socket.on('message', (data) => {
19	    // Relay the frame back to the sender.
20	    socket.send(data.toString());
21	  });
22	});
23	
24	wss.on('listening', () => {
25	  console.log(`collab-msg WebSocket relay listening on ${HOST}:${PORT} (ws ${require('ws/package.json').version})`);
26	});
27	
28	wss.on('error', (err) => {
29	  console.error('collab-msg server error:', err.message);
30	  process.exit(1);
31	});
32	
33	process.on('SIGTERM', () => wss.close(() => process.exit(0)));
34	process.on('SIGINT', () => wss.close(() => process.exit(0)));
