1	'use strict';
2	// Round-trip probe: open a WebSocket to the local collab-msg relay, send one message,
3	// and confirm the relay echoes it back. Used by bin/roundtrip.sh to verify the service
4	// is up and relaying after the ws dependency is restored.
5	const WebSocket = require('ws');
6	
7	const PORT = process.env.COLLAB_PORT ? Number(process.env.COLLAB_PORT) : 8081;
8	const msg = process.argv[2] || 'collab-roundtrip';
9	
10	const sock = new WebSocket(`ws://127.0.0.1:${PORT}`);
11	
12	sock.on('open', () => sock.send(msg));
13	
14	sock.on('message', (data) => {
15	  const got = data.toString();
16	  console.log(`RECV ${got}`);
17	  sock.close();
18	  process.exit(got === msg ? 0 : 2);
19	});
20	
21	sock.on('error', (err) => {
22	  console.error(`ERR ${err.message}`);
23	  process.exit(3);
24	});
25	
26	setTimeout(() => {
27	  console.error('TIMEOUT waiting for echo');
28	  process.exit(4);
29	}, 8000);
